def shortest_span(values, threshold):
    if not values:
        return 0

    n = len(values)
    prefix_sums = [0] * (n + 1)
    for i in range(n):
        prefix_sums[i + 1] = prefix_sums[i] + values[i]

    min_length = float('inf')
    for i in range(n):
        for j in range(i, n):
            if prefix_sums[j + 1] - prefix_sums[i] >= threshold:
                min_length = min(min_length, j - i + 1)

    return min_length if min_length != float('inf') else 0

from collections import defaultdict, deque

def build_layers(n, prerequisites):
    graph = defaultdict(list)
    in_degree = [0] * n
    for a, b in prerequisites:
        graph[a].append(b)
        in_degree[b] += 1

    sources = deque([i for i in range(n) if in_degree[i] == 0])
    layers = []

    while sources:
        layer = []
        for _ in range(len(sources)):
            current = sources.popleft()
            layer.append(current)
            for neighbor in graph[current]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    sources.append(neighbor)
        layers.append(layer)

    return layers if len(layers) == n else []

def top_words(words, k):
    if k <= 0:
        return []

    word_counts = {}
    for word in words:
        word_counts[word] = word_counts.get(word, 0) + 1

    sorted_words = sorted(word_counts.items(), key=lambda x: (-x[1], x[0]))

    return [word for word, count in sorted_words[:k]]

